    # Get parameters
    PA=PA[0]
    Na=6.023e23
    Width_PM = 1e-7 # In dm
    K_ILM_f = PA["k_ILM_f"].values[0]/(Na*PA["vol_EC"].values[0])
    K_ILM_b = PA["k_ILM_b"].values[0]
    K_IL_RA_f = PA["k_IL_RA_f"].values[0]/(Na*PA["vol_EC"].values[0])
